import { Component, computed, signal } from "@angular/core";
@Component({
  selector: "app-root",
  standalone: true,
  template: `<main><h1>Compteur</h1><p>{{ double() }}</p>
    <button type="button" (click)="incrementer()">Ajouter</button></main>`
})
export class App {
  readonly compte = signal(0);
  readonly double = computed(() => this.compte() * 2);
  incrementer() { this.compte.update(n => n + 1); }
}
